# Creates the release signing key, once.
#
# Everything secret stays in this process. The private key is generated by the OS, exported into a
# byte array, protected with DPAPI (CurrentUser) and written only in that protected form -- no
# PKCS#8, no PEM, nothing plaintext reaches the disk at any point. Nothing secret is printed.
#
# It refuses to run a second time. A signing key that gets quietly replaced is worse than one that
# is missing: everything signed with the old one stops verifying, and the failure looks like
# tampering.

$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Security

$root = Join-Path $env:LOCALAPPDATA 'GNLink\ReleaseSigning'
if (Test-Path $root) {
  # Anything already here means a key exists, or an earlier attempt stopped part-way and left a
  # marker. Either way this is not the moment to overwrite.
  Write-Output "REFUSED: $root already exists"
  exit 2
}

# P-256 SubjectPublicKeyInfo, DER. Everything before the point is fixed for this curve:
#   30 59            SEQUENCE, 89 bytes
#     30 13          SEQUENCE, 19 bytes  -- AlgorithmIdentifier
#       06 07 2A 86 48 CE 3D 02 01        OID 1.2.840.10045.2.1   ecPublicKey
#       06 08 2A 86 48 CE 3D 03 01 07     OID 1.2.840.10045.3.1.7 prime256v1
#     03 42 00       BIT STRING, 66 bytes, 0 unused
#       04 <X:32> <Y:32>                  uncompressed point
# 27 bytes of prefix + 64 = 91. Built by hand because ExportSubjectPublicKeyInfo() is .NET Core
# 3.0 and up, and this runs on Windows PowerShell.
#
# It matters that this is the REAL SPKI. The first version hashed CngKeyBlobFormat::EccPublicBlob
# -- a BCRYPT_ECCKEY_BLOB, magic + cbKey + X + Y -- and called the result an SPKI fingerprint.
# Anyone later comparing against `openssl ... -pubin -outform DER | sha256sum` would have got a
# mismatch and concluded the key was wrong. A label that lies is worse than no label.
$spkiPrefix = [byte[]](0x30,0x59,0x30,0x13,0x06,0x07,0x2A,0x86,0x48,0xCE,0x3D,0x02,0x01,
                       0x06,0x08,0x2A,0x86,0x48,0xCE,0x3D,0x03,0x01,0x07,0x03,0x42,0x00,0x04)

$key = $null
$priv = $null
$roundTrip = $null
$dir = $null
$wroteSomething = $false
try {
  $params = New-Object System.Security.Cryptography.CngKeyCreationParameters
  $params.ExportPolicy = [System.Security.Cryptography.CngExportPolicies]::AllowPlaintextExport
  # No name, so the key is ephemeral: it lives in this process and is not left in a key container
  # where something else could reach it.
  $key = [System.Security.Cryptography.CngKey]::Create(
    [System.Security.Cryptography.CngAlgorithm]::ECDsaP256, $null, $params)

  # BCRYPT_ECCKEY_BLOB: magic + cbKey, then X, Y, d. Compact, and it re-imports without a parser.
  $priv = $key.Export([System.Security.Cryptography.CngKeyBlobFormat]::EccPrivateBlob)

  $ecdsa = New-Object System.Security.Cryptography.ECDsaCng($key)
  $pub = $ecdsa.ExportParameters($false)
  if ($pub.Q.X.Length -ne 32 -or $pub.Q.Y.Length -ne 32) {
    throw "unexpected coordinate size $($pub.Q.X.Length)/$($pub.Q.Y.Length)"
  }
  $xy = New-Object byte[] 64
  [Array]::Copy($pub.Q.X, 0, $xy, 0, 32)
  [Array]::Copy($pub.Q.Y, 0, $xy, 32, 32)
  $xyHex = ([System.BitConverter]::ToString($xy) -replace '-', '').ToLowerInvariant()

  $spki = $spkiPrefix + $xy
  if ($spki.Length -ne 91) { throw "SPKI came out $($spki.Length) bytes, expected 91" }
  $sha = [System.Security.Cryptography.SHA256]::Create()
  $spkiFp = ([System.BitConverter]::ToString($sha.ComputeHash($spki)) -replace '-', '').ToLowerInvariant()
  $idFp = ([System.BitConverter]::ToString($sha.ComputeHash($xy)) -replace '-', '').ToLowerInvariant()
  $keyId = 'p256-' + $idFp.Substring(0, 16)

  $protectedBlob = [System.Security.Cryptography.ProtectedData]::Protect(
    $priv, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)

  # ---------------------------------------------------------------- can what we are about to
  # store actually be used?
  #
  # Wrapping bytes and writing them is not evidence that a key was made. Without this, an
  # unusable blob would be written, reported as success, and discovered only when the first real
  # release failed to sign. So: unprotect it, import it, sign with it, and verify that signature
  # against the PUBLIC HEX WE ARE ABOUT TO RECORD -- which also checks that the two files we write
  # belong to each other.
  $roundTrip = [System.Security.Cryptography.ProtectedData]::Unprotect(
    $protectedBlob, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
  $reimported = [System.Security.Cryptography.CngKey]::Import(
    $roundTrip, [System.Security.Cryptography.CngKeyBlobFormat]::EccPrivateBlob)
  $signer = New-Object System.Security.Cryptography.ECDsaCng($reimported)
  $signer.HashAlgorithm = [System.Security.Cryptography.CngAlgorithm]::Sha256
  $probe = [System.Text.Encoding]::UTF8.GetBytes('gnlink release key round-trip probe')
  $sig = $signer.SignData($probe)

  # The verifier is built from the recorded hex, not from the key object, so this fails if the two
  # ever disagree.
  $verifyBlob = New-Object byte[] (8 + 64)
  [Array]::Copy([byte[]](0x45,0x43,0x53,0x31), 0, $verifyBlob, 0, 4)   # BCRYPT_ECDSA_PUBLIC_P256_MAGIC
  [Array]::Copy([System.BitConverter]::GetBytes([int]32), 0, $verifyBlob, 4, 4)
  [Array]::Copy($xy, 0, $verifyBlob, 8, 64)
  $verifyKey = [System.Security.Cryptography.CngKey]::Import(
    $verifyBlob, [System.Security.Cryptography.CngKeyBlobFormat]::EccPublicBlob)
  $verifier = New-Object System.Security.Cryptography.ECDsaCng($verifyKey)
  $verifier.HashAlgorithm = [System.Security.Cryptography.CngAlgorithm]::Sha256
  if (-not $verifier.VerifyData($probe, $sig)) {
    throw 'the stored key did not verify against the public hex -- nothing written'
  }
  # And the negative half, so "it verifies" is not just "it always says yes".
  $probe[0] = $probe[0] -bxor 0x01
  if ($verifier.VerifyData($probe, $sig)) {
    throw 'verification accepted a tampered probe -- nothing written'
  }
  $signer.Dispose(); $verifier.Dispose(); $reimported.Dispose(); $verifyKey.Dispose()

  # ---------------------------------------------------------------- only now, write
  $dir = Join-Path $root $keyId
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
  $wroteSomething = $true
  [System.IO.File]::WriteAllBytes((Join-Path $dir 'private.ecc.dpapi'), $protectedBlob)
  [System.IO.File]::WriteAllText((Join-Path $dir 'public_xy.hex'), $xyHex)
  [System.IO.File]::WriteAllText((Join-Path $dir 'spki_sha256.txt'), $spkiFp)
  [System.IO.File]::WriteAllText((Join-Path $dir 'README.txt'), @"
GNLink release signing key.

private.ecc.dpapi  BCRYPT_ECCKEY_BLOB (P-256 private), DPAPI CurrentUser. Readable only by this
                   Windows account on this machine. NOT a backup of anything: if the profile or
                   the machine goes, so does the key.
public_xy.hex      raw X||Y, 128 lowercase hex. THIS is the value the product embeds
                   (trusted_public_key_hex / UPDATE_PUBLIC_KEY_HEX). All three verifiers reject
                   anything that is not 64 bytes, silently -- an SPKI here would be accepted by
                   the hex decoder and then ignored for ever.
spki_sha256.txt    SHA-256 of the X.509 SubjectPublicKeyInfo DER (91 bytes). An identifier for
                   records, comparable with `openssl ... -pubin -outform DER | sha256sum`.
                   NOT for embedding.
"@)

  # ---------------------------------------------------------------- who can read it
  $acl = Get-Acl $dir
  Write-Output "KEYID  $keyId"
  Write-Output "PUBXY  $xyHex"
  Write-Output "SPKI   $spkiFp"
  Write-Output "DIR    $dir"
  Write-Output "OWNER  $($acl.Owner)"
  foreach ($ace in $acl.Access) {
    $who = $ace.IdentityReference.Value
    # Named rather than summarised: "the ACL looked fine" is not a check.
    Write-Output ("ACE    {0} | {1} | inherited={2}" -f $who, $ace.FileSystemRights, $ace.IsInherited)
  }
}
catch {
  Write-Output "FAILED: $_"
  if ($wroteSomething -and $dir) {
    # NOT deleted. This is outside the repository root, and removing things out there is
    # forbidden however sure I am that I made them -- the same rule a test suite in this project
    # broke by deleting %TEMP% directories it had created. A marker is left instead, so the guard
    # at the top of this script stops the next run, and a person decides what happens to it.
    try {
      [System.IO.File]::WriteAllText((Join-Path $dir 'INCOMPLETE.txt'),
        "This key generation did not finish. Nothing here is usable. Left in place deliberately: this script does not delete outside the repository. Remove it by hand before trying again.")
    } catch { }
    Write-Output "LEFT IN PLACE (not deleted, decide by hand): $dir"
  }
  exit 1
}
finally {
  # The plaintext private material is overwritten before this process lets go of it.
  if ($priv) { [Array]::Clear($priv, 0, $priv.Length) }
  if ($roundTrip) { [Array]::Clear($roundTrip, 0, $roundTrip.Length) }
  if ($key) { $key.Dispose() }
}
